package com.lectoria.app.support

import java.io.ByteArrayOutputStream
import java.util.zip.CRC32
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream

/** Synthetic documents generated by tests; no user books are stored in the repository. */
object DocumentFixtures {
    val container = """<?xml version="1.0"?><container xmlns="urn:oasis:names:tc:opendocument:xmlns:container" version="1.0"><rootfiles><rootfile full-path="OEBPS/package.opf" media-type="application/oebps-package+xml"/></rootfiles></container>"""

    fun epub(
        title: String = "Libro sintético",
        author: String = "Autora de prueba",
        containerXml: String = container,
        extra: Map<String, ByteArray> = emptyMap(),
        opfOverride: String? = null,
        cover: ByteArray? = null,
        additionalChapter: String? = null,
    ): ByteArray {
        val opf = opfOverride ?: """<?xml version="1.0" encoding="UTF-8"?>
            <package xmlns="http://www.idpf.org/2007/opf" version="3.0" unique-identifier="id">
              <metadata xmlns:dc="http://purl.org/dc/elements/1.1/">
                <dc:identifier id="id">urn:test:synthetic</dc:identifier><dc:language>es</dc:language>
                <dc:title>${escape(title)}</dc:title><dc:creator>${escape(author)}</dc:creator><meta property="dcterms:modified">2026-11-23T00:00:00Z</meta>
              </metadata>
              <manifest><item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav"/><item id="chapter" href="chapter.xhtml" media-type="application/xhtml+xml"/>
                ${if (cover != null) """<item id="cover" href="cover.png" media-type="image/png" properties="cover-image"/>""" else ""}
                ${if (additionalChapter != null) """<item id="chapter2" href="chapter2.xhtml" media-type="application/xhtml+xml"/>""" else ""}
              </manifest><spine><itemref idref="chapter"/>${if (additionalChapter != null) """<itemref idref="chapter2"/>""" else ""}</spine>
            </package>""".trimIndent()
        val entries = linkedMapOf(
            "mimetype" to "application/epub+zip".toByteArray(),
            "META-INF/container.xml" to containerXml.toByteArray(),
            "OEBPS/package.opf" to opf.toByteArray(),
            "OEBPS/chapter.xhtml" to """<html xmlns="http://www.w3.org/1999/xhtml"><head><title>Prueba</title></head><body><p>Lectura sintética con tildes: canción.</p></body></html>""".toByteArray(),
        )
        entries["OEBPS/nav.xhtml"] = """<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops"><head><title>Índice</title></head><body><nav epub:type="toc"><ol><li><a href="chapter.xhtml">Prueba</a></li></ol></nav></body></html>""".toByteArray()
        if (cover != null) entries["OEBPS/cover.png"] = cover
        if (additionalChapter != null) entries["OEBPS/chapter2.xhtml"] = additionalChapter.toByteArray()
        entries.putAll(extra)
        return zip(entries)
    }

    fun zip(entries: Map<String, ByteArray>): ByteArray = ByteArrayOutputStream().also { output ->
        ZipOutputStream(output).use { zip ->
            entries.forEach { (name, bytes) ->
                val entry = ZipEntry(name)
                if (name == "mimetype") {
                    entry.method = ZipEntry.STORED
                    entry.size = bytes.size.toLong()
                    entry.compressedSize = bytes.size.toLong()
                    entry.crc = CRC32().apply { update(bytes) }.value
                }
                zip.putNextEntry(entry)
                zip.write(bytes)
                zip.closeEntry()
            }
        }
    }.toByteArray()

    fun pdf(textual: Boolean = true): ByteArray {
        val stream = if (textual) "BT /F1 18 Tf 40 100 Td (Texto sintetico) Tj ET\n" else "40 40 120 80 re f\n"
        val objects = listOf(
            "<< /Type /Catalog /Pages 2 0 R >>",
            "<< /Type /Pages /Count 1 /Kids [3 0 R] >>",
            "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 200] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>",
            "<< /Length ${stream.length} >>\nstream\n${stream}endstream",
            "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
        )
        val output = ByteArrayOutputStream()
        fun write(value: String) { output.write(value.toByteArray(Charsets.ISO_8859_1)) }
        write("%PDF-1.4\n")
        val offsets = objects.mapIndexed { index, body ->
            val offset = output.size()
            write("${index + 1} 0 obj\n$body\nendobj\n")
            offset
        }
        val xref = output.size()
        write("xref\n0 ${objects.size + 1}\n0000000000 65535 f \n")
        offsets.forEach { write("%010d 00000 n \n".format(java.util.Locale.ROOT, it)) }
        write("trailer\n<< /Size ${objects.size + 1} /Root 1 0 R >>\nstartxref\n$xref\n%%EOF\n")
        return output.toByteArray()
    }

    private fun escape(value: String) = value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
}
